import math

# Global state for wind period detection
global_state = {
    'wind_period': None,
    'prev_peak_time': None,
    'prev_peak_vx': 0.0,
    'target_x_min': 9.35,
    'target_x_max': 10.65,
    'target_y': 11.7,
}

def build_agent(sandbox):
    # No additional structures needed as the seat is already in the build zone
    return None

def agent_action(sandbox, agent_body, step_count):
    global global_state
    seat = sandbox.get_swing_seat()
    pos = seat.position
    vel = seat.linearVelocity
    x, y = pos.x, pos.y
    vx, vy = vel.x, vel.y
    current_time = sandbox.get_sim_time()

    # Wind period detection
    if global_state['wind_period'] is None:
        if global_state['prev_peak_time'] is None:
            global_state['prev_peak_time'] = current_time
            global_state['prev_peak_vx'] = vx
        else:
            if abs(vx) > abs(global_state['prev_peak_vx']):
                # New peak detected
                wind_period_candidate = current_time - global_state['prev_peak_time']
                global_state['wind_period'] = wind_period_candidate
                global_state['prev_peak_time'] = current_time
                global_state['prev_peak_vx'] = vx
            else:
                global_state['prev_peak_vx'] = vx
    else:
        # Apply wind counteraction
        wind_phase = 2 * math.pi * current_time / global_state['wind_period']
        wind_direction = math.sin(wind_phase)
        fx_wind = -wind_direction * 42.0  # Max force to counteract wind
        sandbox.apply_force_to_seat(fx_wind, 0)

    # Pump at the bottom of the swing (y near 6.0m)
    if abs(y - 6.0) < 0.1 and abs(vx) > 0.1:
        fx_pump = 42.0 * (vx / abs(vx))  # Apply force in direction of motion
        sandbox.apply_force_to_seat(fx_pump, 0)

    # Adjust horizontal position towards target x range
    else:
        target_x_center = (global_state['target_x_min'] + global_state['target_x_max']) / 2
        if x < target_x_center:
            # Apply rightward force
            if vx > 0:
                fx_pump = 42.0
            else:
                fx_pump = -42.0
        elif x > target_x_center:
            # Apply leftward force
            if vx < 0:
                fx_pump = -42.0
            else:
                fx_pump = 42.0
        else:
            fx_pump = 0.0
        sandbox.apply_force_to_seat(fx_pump, 0)

    # Check if in target zone
    if y >= global_state['target_y'] and x >= global_state['target_x_min'] and x <= global_state['target_x_max']:
        return  # Success
